SourceCode.Declaration:
/// <summary>
/// Validation class for outbound to an azure fileshare
/// </summary>
class OMGAzureValidator_OutboundFileShare extends OMGAzureValidator_FileShare
{
}

Method.Source:
/// <summary>
/// Validating the Azure components
/// </summary>
/// <returns>True if all ok</returns>
public boolean validateOutboundFileShare()
{
    OMGOutboundDataContract_AzureFileShare  dataContract = dataContract_Azure;
    boolean                                 ret = true;
    ;

    if (!dataContract.parmFileShareName())
    {
        ret = checkFailed("@OMG:FileShareNameMissing");
    }
    if (!dataContract.parmTargetDirectory())
    {
        ret = checkFailed("@OMG:TargetDirectoryMissing");
    }

    if (ret)
    {
        ret = this.checkFileShareExist(dataContract.parmFileShareName());

        if (ret)
        {
            ret = this.checkDirectoryExist(dataContract.parmTargetDirectory());
        }
    }

    if (!dataContract.parmFileType())
    {
        ret = checkFailed("@OMG:FileTypeMissing");
    }

    if (!dataContract.parmFilenamePattern())
    {
        ret = checkFailed("@OMG:FilenamePatternMissing");
    }

    return ret;
}

/// <summary>
/// Calls super, and if that is ok checks the outbound file share
/// </summary>
/// <returns>True if all ok</returns>
public boolean validate()
{
    boolean ret = super();

    ret = ret && this.validateOutboundFileShare();

    return ret;
}
